const b = $json.body || $json;
if (!b.legal_entity_id) throw new Error('Missing legal_entity_id');
if (!b.search && !b.request) throw new Error('Provide search or request');
return [{json: b}];

const term = ($json.search || '').replace(/'/g, "''");
const legal = Number($json.legal_entity_id);
const sql = `SELECT id, name, email, department, squad FROM employees WHERE legal_entity_id=${legal} AND active=1 AND (name LIKE '%${term}%' OR email LIKE '%${term}%') LIMIT 25`;
return [{json: {...$json, sql}}];

const sql = $json.sql || $json.data?.sql || $json.body?.sql;
if (!sql) throw new Error('Missing SQL to execute');
return [{json: {legal_entity_id: $json.legal_entity_id, sql}}];
